package com.example.portico;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;

import com.example.portico.entidad.Comida;

@SpringBootApplication
public class PorticoApplication {

@Bean
public Comida comida(){
    return Comida.builder()
        .id(1)
        .name("Hamburguesa_1")
        .price(10000)
        .description("Esta buena")
        .imagen("data:image/webp;base64,")
        .build();
}


	public static void main(String[] args) {
		SpringApplication.run(PorticoApplication.class, args);
	}

}
